<script lang="ts">import {onMount} from 'svelte';import type {WorkbenchState} from '../lib/workbench-state.js';export let state:WorkbenchState;let selection:any;onMount(()=>state.subscribe(value=>selection=value.selection));</script>
<section class="panel details-panel"><header><strong>Inspector</strong></header>{#if selection}<div class="detail-title">{selection.label??selection.name??selection.id}</div><dl>{#each Object.entries(selection) as [key,value]}<dt>{key}</dt><dd>{typeof value==='object'?JSON.stringify(value):String(value)}</dd>{/each}</dl>{:else}<div class="empty-copy">Select a graph node, file, process, or function to inspect its evidence.</div>{/if}</section>
